module isochronous_4phase_handshake (
    input  src_clk_i,
    input  src_rst_ni,
    input  src_valid_i,
    output src_ready_o,
    input  dst_clk_i,
    input  dst_rst_ni,
    output dst_valid_o,
    input  dst_ready_i
);

reg src_valid_sync;
reg src_valid_sync2;
reg dst_ready_sync;
reg dst_ready_sync2;
reg src_valid_pulse;
reg dst_valid_pulse;
reg src_ready_pulse;
reg dst_ready_pulse;

always @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
        src_valid_sync <= 1'b0;
        src_valid_sync2 <= 1'b0;
        src_valid_pulse <= 1'b0;
    end else begin
        src_valid_sync <= src_valid_i;
        src_valid_sync2 <= src_valid_sync;
        src_valid_pulse <= src_valid_sync && !src_valid_sync2;
    end
end

always @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
        dst_ready_sync <= 1'b0;
        dst_ready_sync2 <= 1'b0;
        dst_ready_pulse <= 1'b0;
    end else begin
        dst_ready_sync <= dst_ready_i;
        dst_ready_sync2 <= dst_ready_sync;
        dst_ready_pulse <= dst_ready_sync && !dst_ready_sync2;
    end
end

reg src_state;
reg dst_state;

always @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
        src_state <= 2'b00;
        src_ready_o <= 1'b0;
    end else begin
        case (src_state)
            2'b00: begin
                if (src_valid_i) begin
                    src_state <= 2'b01;
                    src_ready_o <= 1'b1;
                end
            end
            2'b01: begin
                if (dst_ready_sync2) begin
                    src_state <= 2'b10;
                end
            end
            2'b10: begin
                if (!src_valid_i) begin
                    src_state <= 2'b11;
                end
            end
            2'b11: begin
                if (!dst_ready_sync2) begin
                    src_state <= 2'b00;
                    src_ready_o <= 1'b0;
                end
            end
        endcase
    end
end

always @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
        dst_state <= 2'b00;
        dst_valid_o <= 1'b0;
    end else begin
        case (dst_state)
            2'b00: begin
                if (src_valid_sync2) begin
                    dst_state <= 2'b01;
                    dst_valid_o <= 1'b1;
                end
            end
            2'b01: begin
                if (dst_ready_i) begin
                    dst_state <= 2'b10;
                end
            end
            2'b10: begin
                if (!src_valid_sync2) begin
                    dst_state <= 2'b11;
                end
            end
            2'b11: begin
                if (!dst_ready_i) begin
                    dst_state <= 2'b00;
                    dst_valid_o <= 1'b0;
                end
            end
        endcase
    end
end

endmodule
